  builder_.add_PERIOD_S(PERIOD_S);
  builder_.add_APOAPSIS_RADIUS_KM(APOAPSIS_RADIUS_KM);
  builder_.add_PERIAPSIS_RADIUS_KM(PERIAPSIS_RADIUS_KM);
  builder_.add_ECCENTRICITY(ECCENTRICITY);
  builder_.add_SEMI_MAJOR_AXIS_KM(SEMI_MAJOR_AXIS_KM);
  builder_.add_DURATION_S(DURATION_S);
  builder_.add_START_OFFSET_S(START_OFFSET_S);
  builder_.add_TRAJECTORY(TRAJECTORY);
  builder_.add_SOLVER(SOLVER);
  builder_.add_END_STATE(END_STATE);
  builder_.add_START_STATE(START_STATE);
  builder_.add_REVOLUTIONS(REVOLUTIONS);
  builder_.add_NAME(NAME);
  builder_.add_STATE_AXES(STATE_AXES);
  builder_.add_CONIC(CONIC);
