inline ::flatbuffers::Offset<mplOption> CreatemplOption(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> NAME = 0,
    bool SELECTED = false,
    uint32_t REVOLUTIONS = 0,
    mplLambertBranch BRANCH = mplLambertBranch_Unspecified,
    mplPhasingDirection DIRECTION = mplPhasingDirection_Shortest,
    double PHASE_ANGLE_DEG = 0.0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> BURN_DELTA_V_KM_S = 0,
    double TOTAL_DELTA_V_KM_S = 0.0,
    double TOTAL_TIME_S = 0.0,
    double SEMI_MAJOR_AXIS_KM = 0.0,
    bool CLAMPED_TO_FLOOR = false,
    bool WITHIN_BUDGET = false) {
  mplOptionBuilder builder_(_fbb);
  builder_.add_SEMI_MAJOR_AXIS_KM(SEMI_MAJOR_AXIS_KM);
  builder_.add_TOTAL_TIME_S(TOTAL_TIME_S);
  builder_.add_TOTAL_DELTA_V_KM_S(TOTAL_DELTA_V_KM_S);
  builder_.add_PHASE_ANGLE_DEG(PHASE_ANGLE_DEG);
  builder_.add_BURN_DELTA_V_KM_S(BURN_DELTA_V_KM_S);
  builder_.add_REVOLUTIONS(REVOLUTIONS);
  builder_.add_NAME(NAME);
  builder_.add_WITHIN_BUDGET(WITHIN_BUDGET);
  builder_.add_CLAMPED_TO_FLOOR(CLAMPED_TO_FLOOR);
  builder_.add_DIRECTION(DIRECTION);
  builder_.add_BRANCH(BRANCH);
  builder_.add_SELECTED(SELECTED);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<mplOption> CreatemplOptionDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const char *NAME = nullptr,
    bool SELECTED = false,
    uint32_t REVOLUTIONS = 0,
    mplLambertBranch BRANCH = mplLambertBranch_Unspecified,
    mplPhasingDirection DIRECTION = mplPhasingDirection_Shortest,
    double PHASE_ANGLE_DEG = 0.0,
    const std::vector<double> *BURN_DELTA_V_KM_S = nullptr,
    double TOTAL_DELTA_V_KM_S = 0.0,
    double TOTAL_TIME_S = 0.0,
    double SEMI_MAJOR_AXIS_KM = 0.0,
    bool CLAMPED_TO_FLOOR = false,
    bool WITHIN_BUDGET = false) {
  auto NAME__ = NAME ? _fbb.CreateString(NAME) : 0;
  auto BURN_DELTA_V_KM_S__ = BURN_DELTA_V_KM_S ? _fbb.CreateVector<double>(*BURN_DELTA_V_KM_S) : 0;
  return CreatemplOption(
      _fbb,
      NAME__,
      SELECTED,
      REVOLUTIONS,
      BRANCH,
      DIRECTION,
      PHASE_ANGLE_DEG,
      BURN_DELTA_V_KM_S__,
      TOTAL_DELTA_V_KM_S,
      TOTAL_TIME_S,
      SEMI_MAJOR_AXIS_KM,
      CLAMPED_TO_FLOOR,
      WITHIN_BUDGET);
}

/// Classical transfer and plane change between circular orbits (Hohmann,
/// BiElliptic, PlaneChange, CombinedTransfer).
